window.__posterData({"id": "alex-haseb", "name": "Alex Haseb", "folder": "Week44_Poster_AlexHaseb", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "//AI gjorde att koden blev kortare och tog bort onödiga rader. Postern fungerar som innan.//\n\nlet cirklar = [50, 200, 360, 550];\nlet bild;\n\n// Importerar bilden\nasync function setup() {\n  bild = await loadImage(\"party.jpg\");\n  createCanvas(600, 800);\n}\n\nfunction draw() {\n  background(255);\n  image(bild, 0, 0, 600, 800);\n\n//AI valde själv att lägga till större discoljus. Jag tycker det passar festtemat men liknar partiklarna jag redan hade.//\n  if (mouseIsPressed) {\n    noStroke();\nfill(random(255), random(255), random(255), 150);\ncircle(random(width), random(height), 250);\n  }\n\n  // Texten\n  push();\n  translate(300, 400);\n  textAlign(CENTER);\n  textFont(\"ANTON\");\n\n  if (mouseIsPressed) {\n    rotate(sin(frameCount * 0.5) * 0.010);\n    fill(random(255), random(255), random(255));\n  } else {\n    fill(0);\n  }\n\n  noStroke();\n  textSize(70);\n  text(\"Alex Hasebs\", 0, 0);\n  text(\"DJ PARTY\", 0, 60);\n  text(\"VÄLKOMMEN\", 0, 320);\n  pop();\n\n  // Partiklar vid musklick\n  if (mouseIsPressed) {\n    fill(random(255), random(255), random(255));\n    noStroke();\n    circle(random(width), random(height), 60);\n  } else {\n    fill(0);\n  }\n\n//Jag bad AI'n att göra lamporna pulserande när man klickar med musen. Lamporna känns nu mer levande.//\nlet storlek = 50;\n\nif (mouseIsPressed) {\n  storlek = 50 + sin(frameCount * 0.1) * 15;\n}\n\nfor (let i = 0; i < cirklar.length; i++) {\n  circle(cirklar[i], 30, storlek);\n  circle(cirklar[i], 770, storlek);\n  circle(30, cirklar[i] + 80, storlek);\n  circle(570, cirklar[i] + 80, storlek);\n}\n\n  // Ramen\n  noFill();\n  strokeWeight(10);\n\n  if (mouseIsPressed) {\n    stroke(random(255), random(255), random(255));\n  } else {\n    stroke(0);\n  }\n\n  rect(10, 10, 580, 780);\n}\n", "assets": {"party.jpg": {"mime": "image/webp", "b64": ""}}});
